/**
 * Unit tests for MutableDateTime#addWeeks
 */
public class MutableDateTime_addWeeks_TriageGen0Test {

    @Test
    public void testAddWeeksPositive() {
        // Initialize at a known date: 2023-01-01 (Sunday)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        // Add 2 weeks
        dt.addWeeks(2);

        // Expected: 2023-01-15
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }












}

