public class MutableDateTime_addWeeks_TriageGen0Test {





    @Test
    public void testAddWeeksZero() {
        // Initialize at a known date
        MutableDateTime dt = new MutableDateTime(2023, 5, 20, 10, 30, 0, 0);
        long originalMillis = dt.getMillis();

        // Add 0 weeks
        dt.addWeeks(0);

        // Expected: No change
