public class MutableDateTime_addWeeks_TriageGen0Test {











    @Test
    public void testAddWeeksLargeValue() {
        // Start at epoch
        MutableDateTime dt = new MutableDateTime(0); 

        // Add a large number of weeks (e.g., 52 weeks = 1 year roughly)
        dt.addWeeks(52);

        // Verify it's not the same as epoch and has progressed
        assertTrue(dt.getMillis() > 0);
    }


